def sha(b:bytes)->str:return hashlib.sha256(b).hexdigest()
def inflate(s:str)->bytes:return zlib.decompress(base64.b64decode(s))

def replace_exact(root:Path,path:str,before:str,after:str,size:int,data:bytes):
    p=root/path; old=p.read_bytes()
    if sha(old)!=before: raise SystemExit(f'before hash mismatch {path}: {sha(old)}')
    if len(data)!=size or sha(data)!=after: raise SystemExit(f'overlay identity mismatch {path}: {len(data)} {sha(data)}')
    p.write_bytes(data)

def patch_audit(root:Path):
    p=root/AUDIT; b=p.read_bytes()
    if sha(b)!=AUDIT_BEFORE: raise SystemExit(f'before hash mismatch {AUDIT}: {sha(b)}')
    s=b.decode('utf-8')
    for old,new in AUDIT_REPL:
        n=s.count(old)
        if n!=1: raise SystemExit(f'audit replacement count {n} for {old[:80]!r}')
        s=s.replace(old,new)
    out=s.encode('utf-8')
    if len(out)!=AUDIT_BYTES or sha(out)!=AUDIT_AFTER: raise SystemExit(f'audit after identity mismatch {len(out)} {sha(out)}')
    p.write_bytes(out)

def patch_manifest(src:Path,dst:Path):
    m=json.loads(src.read_text(encoding='utf-8')); rows=m['files']
    changes={
      AUDIT:(46347,AUDIT_BEFORE,AUDIT_BYTES,AUDIT_AFTER),
      TOPOLOGY:(18142,TOPOLOGY_BEFORE,TOPOLOGY_BYTES,TOPOLOGY_AFTER),
      SKU:(11197,SKU_BEFORE,SKU_BYTES,SKU_AFTER),
    }
    for path,(before_bytes,before_sha,after_bytes,after_sha) in changes.items():
        hits=[r for r in rows if r['path']==path]
        if len(hits)!=1: raise SystemExit(f'manifest row missing/duplicate: {path}')
        r=hits[0]
        if r['byteLength']!=before_bytes or r['sha256']!=before_sha: raise SystemExit(f'manifest before mismatch: {path}')
        r['byteLength']=after_bytes; r['sha256']=after_sha
    p=m['projection']; p['payloadBytes']=EXPECTED_PAYLOAD; p['sourceContentAggregateSha256']=EXPECTED_AGG
    m['schemaVersion']='velmere.p66.owner-corrected-exact-current-build-relevant-projection.v2'
    m['classification']='CURRENT_SOURCE_EXACT_BUILD_RELEVANT_PROJECTION_WITH_P66_OWNER_TOPOLOGY_AND_AUDIT_PDF_DELTA_NOT_FULL_SOURCE'
    m['p66Delta']={
      'files':[{'path':k,'beforeSha256':v[1],'afterSha256':v[3],'afterByteLength':v[2]} for k,v in changes.items()],
      'ownerTopology':'10 real product families / 20 customer rows / 5 tiered families / 5 standalone no-tier products / 20 current execution profiles / legacy 33 retired as product-completion denominator',
      'pdfModel':'PDF is an Audit/Browser customer artifact, not a standalone product family',
    }
    m['truthBoundary']='P66 exact Windows engineering proof for the 1597-file build-relevant projection with owner-corrected topology and Audit Basic PDF support. No final customer, current-data, rights, paid-value, sale, LIVE or WORLD_CLASS credit.'
    pathset=hashlib.sha256('\n'.join(x['path'] for x in rows).encode()).hexdigest(); agg=hashlib.sha256(); payload=0
    for x in rows:
        payload+=x['byteLength']; agg.update(f"{x['path']}\0{x['byteLength']}\0{x['sha256']}\n".encode())
    if len(rows)!=EXPECTED_FILE_COUNT or pathset!=EXPECTED_PATHSET or payload!=EXPECTED_PAYLOAD or agg.hexdigest()!=EXPECTED_AGG:
        raise SystemExit(f'manifest aggregate mismatch count={len(rows)} pathset={pathset} payload={payload} aggregate={agg.hexdigest()}')
    dst.parent.mkdir(parents=True,exist_ok=True); dst.write_text(json.dumps(m,indent=2)+'\n',encoding='utf-8')

